// Handle empty input gracefully
const data = items.map(item => item.json);

// If no data today, return zeros
if (data.length === 0) {
  return [{
    json: {
      summary: {
        totalLeads: 0,
        newLeads: 0,
        existingLeads: 0,
        warmLeads: 0,
        coldLeads: 0,
        hotLeads: 0,
        meetingsScheduled: 0,
        sourceBreakdown: {},
        channelBreakdown: {}
      }
    }
  }];
}

const normalize = (val) => (val || "").toString().trim().toLowerCase();

let newLeads = 0, existingLeads = 0;
let warmLeads = 0, coldLeads = 0, hotLeads = 0;
let meetingsScheduled = 0;
let sourceCount = {}, channelCount = {};

for (const row of data) {
  const leadStatus = normalize(row["Lead_staus"]);
  if (leadStatus.includes("new")) newLeads++;
  else if (leadStatus.includes("existing")) existingLeads++;

  const leadTemp = normalize(row["Lead type"]);
  if (leadTemp === "warm") warmLeads++;
  else if (leadTemp === "cold") coldLeads++;
  else if (leadTemp === "hot") hotLeads++;

  const pipeline = normalize(row["Pipeline_stage"]);
  if (pipeline.includes("meeting")) meetingsScheduled++;

  let source = normalize(row["Source"]);
  if (!source) source = "direct";
  sourceCount[source] = (sourceCount[source] || 0) + 1;

  let channel = normalize(row["Channel"]);
  if (channel.includes("webiste") || channel.includes("website")) channel = "website form";
  if (!channel) channel = "unknown";
  channelCount[channel] = (channelCount[channel] || 0) + 1;
}

return [{
  json: {
    summary: {
      totalLeads: newLeads + existingLeads,
      newLeads,
      existingLeads,
      warmLeads,
      coldLeads,
      hotLeads,
      meetingsScheduled,
      sourceBreakdown: sourceCount,
      channelBreakdown: channelCount
    }
  }
}];

// Handle empty input gracefully
const row = items[0]?.json || null;

// If no content data today, return defaults
if (!row || Object.keys(row).length === 0) {
  return [{
    json: {
      summary: {
        topic: "No Content Today",
        keyword: "N/A",
        intent: "N/A",
        publishingStatus: {
          wordpress: "No Data ➖",
          facebook: "No Data ➖",
          linkedin: "No Data ➖"
        },
        overallStatus: "No Data for Today ➖"
      }
    }
  }];
}

const normalize = (val) => (val || "").toString().trim().toLowerCase();

const topicTitle = row["topic_title"] || "No Topic";
const keyword = row["topic_keyword"] || "N/A";
const intent = row["intent"] || "N/A";

const blogStatus = normalize(row["Blog_Status"]);
const fbStatus = normalize(row["Facebook_status"]);
const liStatus = normalize(row["LinkedIn_status"]);

const formatStatus = (status) => {
  if (status === "posted") return "Posted ✅";
  if (!status) return "Not Started ❌";
  return "Pending ⏳";
};

let overallStatus = "";
if (blogStatus === "posted" && fbStatus === "posted" && liStatus === "posted") {
  overallStatus = "Fully Published ✅";
} else if (blogStatus || fbStatus || liStatus) {
  overallStatus = "Partially Published ⚠️";
} else {
  overallStatus = "Not Published ❌";
}

return [{
  json: {
    summary: {
      topic: topicTitle,
      keyword,
      intent,
      publishingStatus: {
        wordpress: formatStatus(blogStatus),
        facebook: formatStatus(fbStatus),
        linkedin: formatStatus(liStatus)
      },
      overallStatus
    }
  }
}];

// Safe Overall summary
const getSum = (index) => items[index]?.json?.summary || {};

const leads = getSum(0);
const content = getSum(1);
const voice = getSum(2);
const chatbot = getSum(3);
const appointments = getSum(4);

return [{ json: { leads, content, voice, chatbot, appointments } }];

