// Safe Voice wrapper
const data = items.map(i => i.json);

const today = new Date().toLocaleDateString("en");
const todayData = data.filter(row =>
  (row.Timestamp || "").includes(today)
);

const rows = todayData.length > 0 ? todayData : [];
const totalCalls = rows.length;
let completed = 0, notAnswered = 0, success = 0, partial = 0, failed = 0;

for (const row of rows) {
  const status = (row.Call_status || "").toLowerCase();
  const outcome = (row.Call_outcome || "").toLowerCase();
  if (status === "completed") completed++;
  else if (status.includes("not")) notAnswered++;
  if (outcome === "success") success++;
  else if (outcome === "partial") partial++;
  else if (outcome === "failed") failed++;
}

const connectionRate = totalCalls ? ((completed / totalCalls) * 100).toFixed(1) : "0.0";
const successRate = completed ? ((success / completed) * 100).toFixed(1) : "0.0";
const failureRate = totalCalls ? ((failed / totalCalls) * 100).toFixed(1) : "0.0";

return [{
  json: {
    summary: {
      totalCalls,
      completed,
      notAnswered,
      outcomes: { success, partial, failed },
      metrics: {
        connectionRate: connectionRate + "%",
        successRate: successRate + "%",
        failureRate: failureRate + "%"
      },
      insight: totalCalls === 0
        ? "No calls recorded today."
        : notAnswered > completed
          ? "Majority of failures are due to calls not being answered."
          : successRate > 70
            ? "AI performance is strong when calls are connected."
            : "Call performance needs improvement."
    }
  }
}];

// Safe Chatbot wrapper
const data = items.map(i => i.json);
const today = new Date().toISOString().split('T')[0];
const rows = data.filter(row => (row.created_At || "").includes(today));

let totalConversations = rows.length;
let uniqueSessions = new Set();
let totalDuration = 0, totalLatency = 0, totalTurns = 0, resolvedCount = 0;
let alerts = [];

for (const row of rows) {
  if (row.session_id) uniqueSessions.add(row.session_id);
  totalDuration += Number(row["duration (ms)"] || 0) / 1000;
  totalLatency += Number(row["Avg letancy"] || 0);
  totalTurns += Number(row.turns || 0);
  const res = (row.resolution || "").toLowerCase();
  if (res === "resolved" || res === "success") resolvedCount++;
}

const avgLatency = totalConversations ? (totalLatency / totalConversations).toFixed(2) : 0;
const avgTurns = totalConversations ? (totalTurns / totalConversations).toFixed(2) : 0;
const resolutionRate = totalConversations ? ((resolvedCount / totalConversations) * 100).toFixed(1) : "0.0";

if (avgLatency > 2000) alerts.push("High latency detected ⚠️");
if (resolutionRate < 50) alerts.push("Low resolution rate ⚠️");
if (avgTurns > 10) alerts.push("Conversations are too long ⚠️");
if (totalConversations === 0) alerts.push("No chatbot data for today");

return [{
  json: {
    summary: {
      totalConversations,
      uniqueSessions: uniqueSessions.size,
      performance: {
        avgDurationSeconds: totalConversations ? (totalDuration / totalConversations).toFixed(2) : 0,
        avgLatencyMs: avgLatency,
        avgTurns
      },
      effectiveness: { resolved: resolvedCount, resolutionRate: resolutionRate + "%" },
      alerts
    }
  }
}];

// Safe Appointments wrapper
const data = items.map(i => i.json);
const today = new Date().toLocaleDateString("en");
const rows = data.filter(row => (row.Timestamp || "").includes(today));

let totalBookings = rows.length;
let uniqueUsers = new Set();
let todayAppointments = 0, upcomingAppointments = 0, pastAppointments = 0;
let statusCount = {}, reminderCount = {}, serviceCount = {}, hourCount = {};
let missingReminders = 0;
const todayStr = new Date().toDateString();

for (const row of rows) {
  if (row.User_email) uniqueUsers.add(row.User_email);
  const apptDate = row.Appointmnet_date ? new Date(row.Appointmnet_date).toDateString() : "";
  if (apptDate === todayStr) todayAppointments++;
  else if (new Date(row.Appointmnet_date) > new Date()) upcomingAppointments++;
  else pastAppointments++;

  const status = (row.Appintment_status || "unknown").toLowerCase().trim();
  statusCount[status] = (statusCount[status] || 0) + 1;
  const reminder = (row.Reminder_status || "unknown").toLowerCase().trim();
  reminderCount[reminder] = (reminderCount[reminder] || 0) + 1;
  if (reminder !== "sent") missingReminders++;
  const service = (row.Service || "unknown").trim();
  serviceCount[service] = (serviceCount[service] || 0) + 1;
  const hour = row.Appointment_hour || "unknown";
  hourCount[hour] = (hourCount[hour] || 0) + 1;
}

let peakHour = Object.entries(hourCount).sort((a, b) => b[1] - a[1])[0]?.[0] || "No Data";
let alerts = [];
if ((statusCount["pending"] || 0) > 0) alerts.push(`${statusCount["pending"]} appointments pending`);
if (missingReminders > 0) alerts.push(`${missingReminders} appointments without reminders`);
if (totalBookings === 0) alerts.push("No appointment data for today");

return [{
  json: {
    summary: {
      totalBookings,
      uniqueUsers: uniqueUsers.size,
      schedule: { todayAppointments, upcomingAppointments, pastAppointments },
      statusBreakdown: statusCount,
      reminderBreakdown: reminderCount,
      serviceBreakdown: serviceCount,
      peakHour,
      alerts
    }
  }
}];
